{
  "name": "quota-gate",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "In-process quota gate with fair backpressure",
  "main": "src/index.js",
  "scripts": { "test": "node --test" },
  "engines": { "node": ">=20" }
}

content.content:
1	export class QuotaExceededError extends Error {
2	  constructor(code, message) {
3	    super(message);
4	    this.name = 'QuotaExceededError';
5	    this.code = code;
6	  }
7	}
8	
9	// Internal state of every gate, shared with child gates through a WeakMap so
10	// the public gate object keeps its exact shape.
11	const gateState = new WeakMap();
12	
13	// Monotonic counter that never repeats or moves backwards, independent of the
14	// (mocked, possibly frozen) wall clock; gives queued entries a global arrival
15	// order so reparented queues can merge fairly.
16	let enqueueSeq = 0;
17	
18	// setTimeout/setInterval clamp delays beyond the signed 32-bit range to 1ms,
19	// which would expire a patient waiter — or flip a long window — almost
20	// immediately. Long delays therefore fire in real-time chunks: each fire
21	// consumes one chunk and re-arms the remainder, so the measured wait is real
22	// elapsed time exactly like a single timer.
23	const MAX_TIMER_DELAY = 0x7fffffff;
24	
25	function assertInteger(value, name) {
26	  if (typeof value !== 'number' || !Number.isInteger(value)) {
27	    throw new TypeError(`${name} must be an integer`);
28	  }
29	}
30	
31	function assertSignal(signal) {
32	  if (
33	    signal !== undefined &&
34	    signal !== null &&
35	    (typeof signal !== 'object' ||
36	      typeof signal.addEventListener !== 'function' ||
37	      typeof signal.removeEventListener !== 'function')
38	  ) {
39	    throw new TypeError('signal must be an AbortSignal');
40	  }
41	}
42	
43	export function createGate({ limit, windowMs, maxWaitMs = 0, parent } = {}) {
44	  assertInteger(limit, 'limit');
45	  assertInteger(windowMs, 'windowMs');
46	  assertInteger(maxWaitMs, 'maxWaitMs');
47	  if (limit <= 0) throw new RangeError('limit must be a positive integer');
48	  if (windowMs <= 0) throw new RangeError('windowMs must be a positive integer');
49	  if (maxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');
50	
51	  let parentState = null;
52	  if (parent !== undefined && parent !== null) {
53	    parentState = gateState.get(parent);
54	    if (parentState === undefined) {
55	      throw new TypeError('parent must be a gate created by createGate');
56	    }
57	    if (limit > parentState.limit) {
58	      throw new RangeError('limit must not exceed parent limit');
59	    }
60	  }
61	
62	  const state = {
63	    limit,
64	    windowMs,
65	    maxWaitMs,
66	    parent: parentState,
67	    children: new Set(),
68	    isRoot: parentState === null,
69	    // Own-window accounting.
70	    ownGen: 0, // bumped on every own-window flip, invalidates old handles
71	    usedOwn: 0, // own units occupied or lent out in the current own window
72	    inFlight: 0, // units occupied through this gate and not yet cleared
73	    borrowedInFlight: 0, // units this gate's occupations borrowed, still live
74	    lentInFlight: 0, // own units lent to descendants' admitted occupations
75	    poolDraw: 0, // committed pool charge, valid only when drawGen === poolGen
76	    drawGen: -1,
77	    // Cross-gate reservation accounting. A pending acquireAll first reserves
78	    // the member's own current-window slice, then own slices up the direct
79	    // parent chain (each step registering the lend); the root pool covers the
80	    // remainder. Every gathered unit draws pool room until commit or rollback.
81	    //
82	    // A non-root gate's reserved units are pendingOwn + pendingLends: own
83	    // window units promised to pending combos, as member or as ancestor
84	    // lender. The root's reserved units are poolResvUnits: uncommitted units
85	    // drawn from the pool. Across the family every reserved unit counts once.
86	    rolledBack: 0, // failed whole-combo reservation attempts owned here
87	    pendingOwn: 0,
88	    pendingLends: 0,
89	    resvAsMember: new Set(), // entries holding pendingOwn here
90	    resvAsLender: new Set(), // entries holding pendingLends here
91	    lentLinks: new Set(), // admitted occupation links lent from this gate
92	    // Observability.
93	    waiting: 0, // units currently queued through this gate
94	    granted: 0,
95	    refused: 0,
96	    expired: 0,
97	    cancelled: 0,
98	    openHandles: new Set(),
99	    // Live queue entries entered through this gate. They normally sit in this
100	    // family's queue, but a wholly-moved combo whose entry gate stayed behind
101	    // migrates into another family's queue; the set lets per-gate operations
102	    // (wait-cap retiming) still find them.
103	    ownedEntries: new Set(),
104	    root: null,
105	    timer: null,
106	  };
107	
108	  let root;
109	  if (parentState === null) {
110	    root = state;
111	    // The quota pool shared by the whole hierarchy lives on the root gate.
112	    Object.assign(state, {
113	      poolLimit: limit,
114	      poolGen: 0, // bumped on every root-window flip
115	      poolUsed: 0, // units committed or reserved in the current pool window
116	      poolLinks: new Set(), // admitted pool borrows, reclaimed at the pool flip
117	      poolResv: new Set(), // uncommitted pool reservation links
118	      poolResvUnits: 0, // sum of units behind poolResv
119	      queue: [], // queued requests from every gate, in arrival order
120	      head: 0, // index of the first live entry; entries are never shifted
121	      liveQueued: 0, // entries not yet settled
122	      serveWave: 0, // monotonic count of serves that overtook a blocked combo
123	      minDeadline: Infinity, // earliest live deadline, skips idle sweeps
124	      lastNow: 0, // monotonic clock: never moves backwards
125	      members: new Set(),
126	    });
127	    state.members.add(state);
128	  } else {
129	    root = parentState.root;
130	    root.members.add(state);
131	    parentState.children.add(state);
132	  }
133	  state.root = root;
134	
135	  // Operational helpers read state.root dynamically rather than capturing the
136	  // local `root`: reparent() can move this gate (and its descendants) into
137	  // another family's pool.
138	  function now() {
139	    return rootNow(state.root);
140	  }
141	
142	  function rootNow(r) {
143	    const t = Date.now();
144	    if (t > r.lastNow) r.lastNow = t;
145	    return r.lastNow;
146	  }
147	
148	  function effectiveDraw(node) {
149	    return node.drawGen === node.root.poolGen ? node.poolDraw : 0;
150	  }
151	
152	  function chargeDraw(node, units) {
153	    if (node.drawGen !== node.root.poolGen) {
154	      node.drawGen = node.root.poolGen;
155	      node.poolDraw = 0;
156	    }
157	    node.poolDraw += units;
158	  }
159	
160	  function reservedOn(g) {
161	    return g === g.root ? g.root.poolResvUnits : g.pendingOwn + g.pendingLends;
162	  }
163	
164	  // --- Combo reservations ---------------------------------------------------
165	  //
166	  // seg:  { gate, units, own, ownReleased, links, gen }
167	  // link: { kind:'own'|'pool', lender, units, released, gen }
168	  //
169	  // Gather plans first and applies second, so a plan the pool cannot cover is
170	  // rejected without any mutation and the whole-combo rollback is trivial.
171	  // Sibling members share ancestor chains; the tentative `claimed` map debits
172	  // ancestor headroom cumulatively inside one plan. Every registration is
173	  // intrusive: commit, rollback and window-flip reclaims touch only the gates
174	  // involved, never the queue or the whole family.
175	
176	  function buildSegs(comboGates, unitsOf) {
177	    return comboGates.map((g) => ({
178	      gate: g,
179	      units: unitsOf(g),
180	      own: 0,
181	      ownReleased: false, // member own slice already reclaimed by an own flip
182	      links: [],
183	      gen: -1,
184	    }));
185	  }
186	
187	  function ownHeadroom(g, claimed) {
188	    return Math.max(0, g.limit - g.usedOwn - g.pendingOwn - g.pendingLends - (claimed.get(g) ?? 0));
189	  }
190	
191	  // Pure plan: fills seg.own / seg.links and returns total pool need. A
192	  // member slice larger than that gate's own limit simply borrows the excess
193	  // up the chain — member limits never cap a combo, only the root pool does.
194	  function planGather(segs, r) {
195	    const claimed = new Map();
196	    let poolNeed = 0;
197	    for (const seg of segs) {
198	      const m = seg.gate;
199	      if (m === r) {
200	        seg.links.push({ kind: 'pool', lender: r, units: seg.units, released: false, gen: -1 });
201	        poolNeed += seg.units;
202	        continue;
203	      }
204	      let need = seg.units;
205	      const own = Math.min(need, ownHeadroom(m, claimed));
206	      seg.own = own;
207	      claimed.set(m, (claimed.get(m) ?? 0) + own);
208	      need -= own;
209	      let cur = m.parent;
210	      while (need > 0 && cur !== null && cur !== r) {
211	        const lend = Math.min(need, ownHeadroom(cur, claimed));
212	        if (lend > 0) {
213	          seg.links.push({ kind: 'own', lender: cur, units: lend, released: false, gen: -1 });
214	          claimed.set(cur, (claimed.get(cur) ?? 0) + lend);
215	          need -= lend;
216	        }
217	        cur = cur.parent;
218	      }
219	      if (need > 0) {
220	        seg.links.push({ kind: 'pool', lender: r, units: need, released: false, gen: -1 });
221	        poolNeed += need;
222	      }
223	    }
224	    return poolNeed;
225	  }
226	
227	  // Apply a planned reservation; the caller pre-checked poolNeed against room.
228	  function applyGather(entry, segs) {
229	    // The pool is the one owned by the family whose QUEUE holds the entry; an
230	    // entry can outlive its entry-point gate's family membership when a
231	    // reparent migrates a wholly-moved combo whose owner stayed behind.
232	    const r = entry.qroot;
233	    const gen = r.poolGen;
234	    for (const seg of segs) {
235	      const m = seg.gate;
236	      seg.gen = gen;
237	      seg.ownReleased = false;
238	      if (m !== r && seg.own > 0) {
239	        m.pendingOwn += seg.own;
240	        m.resvAsMember.add(entry);
241	        r.poolUsed += seg.own;
242	      }
243	      for (const link of seg.links) {
244	        link.gen = gen;
245	        r.poolUsed += link.units;
246	        if (link.kind === 'own') {
247	          link.lender.pendingLends += link.units;
248	          link.lender.resvAsLender.add(entry);
249	        } else {
250	          r.poolResv.add(link);
251	          r.poolResvUnits += link.units;
252	          if (m === r) m.resvAsMember.add(entry);
253	        }
254	      }
255	    }
256	    entry.segs = segs;
257	    entry.holdsHeld = true;
258	  }
259	
260	  // Plan, check pool room, apply — or reject without touching anything. The
261	  // whole combo draws pool room: a member's own slice and every ancestor lend
262	  // are partitions OF the pool, not capacity beyond it. Feasibility is
263	  // therefore simply poolUsed + total combo units <= poolLimit; the plan's
264	  // own/lender/pool partition only decides which own window each unit lands
265	  // on (and thus where its flip reclaims it).
266	  function tryGather(entry, segs) {
267	    const r = entry.qroot;
268	    let total = 0;
269	    for (const seg of segs) total += seg.units;
270	    if (r.poolUsed + total > r.poolLimit) {
271	      for (const seg of segs) {
272	        seg.own = 0;
273	        seg.links = [];
274	      }
275	      return false;
276	    }
277	    planGather(segs, r);
278	    applyGather(entry, segs);
279	    return true;
280	  }
281	
282	  // Same whole reservation for one gate: the entry's own current-window slice,
283	  // lends up the direct parent chain, then the root pool. A single-gate
284	  // occupation gathers exactly the way a one-member combo would — its own
285	  // limit never caps the request, only the family pool does.
286	  function tryGatherOne(entry, g, units) {
287	    return tryGather(entry, buildSegs([g], () => units));
288	  }
289	
290	  // Release a held reservation wholesale. Pool room is refunded only while
291	  // the charged pool window is still the current one; a pool flip already
292	  // reclaimed it (the link is marked released and its gen is stale).
293	  function releaseHolds(entry) {
294	    if (!entry.holdsHeld || entry.segs === null) return;
295	    const r = entry.qroot;
296	    for (const seg of entry.segs) {
297	      const m = seg.gate;
298	      if (!seg.ownReleased && seg.own > 0) {
299	        seg.ownReleased = true;
300	        m.pendingOwn -= seg.own;
301	        m.resvAsMember.delete(entry);
302	        if (seg.gen === r.poolGen) r.poolUsed -= seg.own;
303	      }
304	      for (const link of seg.links) {
305	        if (link.released) continue;
306	        link.released = true;
307	        if (link.kind === 'pool') {
308	          // delete() reports whether the link still charged the pool: a pool
309	          // flip already cleared the set and zeroed poolResvUnits, so a stale
310	          // link must not subtract twice.
311	          if (r.poolResv.delete(link)) r.poolResvUnits -= link.units;
312	          m.resvAsMember.delete(entry);
313	        } else {
314	          link.lender.pendingLends -= link.units;
315	          link.lender.resvAsLender.delete(entry);
316	        }
317	        if (link.gen === r.poolGen) r.poolUsed -= link.units;
318	      }
319	    }
320	    entry.holdsHeld = false;
321	    entry.segs = null;
322	  }
323	
324	  // --- Handles --------------------------------------------------------------
325	  //
326	  // The handle exposes exactly one own property, release, as a closure: the
327	  // destructured method called without a receiver works the same. Every link
328	  // remembers the generations of both sides, so a release after either window
329	  // flipped never subtracts quota that flip already settled.
330	
331	  function makeHandle(records) {
332	    let active = true;
333	    return {
334	      release() {
335	        if (!active) return;
336	        active = false;
337	        for (const rec of records) {
338	          const seg = rec.seg;
339	          const m = seg.member;
340	          const r = m.root;
341	          m.openHandles.delete(rec);
342	          if (seg.mgen === m.ownGen && seg.own > 0) {
343	            m.inFlight -= seg.own;
344	          }
345	          for (const link of seg.links) {
346	            const memberLive = seg.mgen === m.ownGen;
347	            const lenderLive =
348	              link.kind === 'pool' ? link.lgen === r.poolGen : link.lgen === link.lender.ownGen;
349	            if (!memberLive || !lenderLive) continue; // a window flip settled it
350	            m.inFlight -= link.units;
351	            m.borrowedInFlight -= link.units;
352	            if (link.kind === 'pool') {
353	              r.poolLinks.delete(link);
354	            } else {
355	              link.lender.lentLinks.delete(link);
356	              link.lender.inFlight -= link.units;
357	              link.lender.lentInFlight -= link.units;
358	            }
359	          }
360	        }
361	      },
362	    };
363	  }
364	
365	  // Commit a fully gathered combo: provisional promises become admitted
366	  // occupations. Pool room was charged at gather time, so poolUsed does not
367	  // move here.
368	  function commitCombo(entry) {
369	    const r = entry.qroot;
370	    const records = [];
371	    const lenderCleanup = new Set();
372	    for (const seg0 of entry.segs) {
373	      const m = seg0.gate;
374	      const units = seg0.units;
375	      chargeDraw(m, units);
376	      let seg;
377	      if (m === r) {
378	        // The root member's whole slice is its own window and drew the pool
379	        // directly; consume its pool reservation link so it does not survive
380	        // the commit as uncommitted quota.
381	        for (const l0 of seg0.links) {
382	          if (l0.kind === 'pool' && r.poolResv.delete(l0)) r.poolResvUnits -= l0.units;
383	        }
384	        m.usedOwn += units;
385	        m.inFlight += units;
386	        m.resvAsMember.delete(entry);
387	        seg = { member: m, units, own: units, mgen: m.ownGen, links: [] };
388	      } else {
389	        const ownPart = seg0.own;
390	        m.usedOwn += ownPart;
391	        m.pendingOwn -= ownPart;
392	        m.resvAsMember.delete(entry);
393	        m.inFlight += units;
394	        const links = [];
395	        for (const l0 of seg0.links) {
396	          const link = {
397	            kind: l0.kind,
398	            lender: l0.lender,
399	            member: m,
400	            units: l0.units,
401	            lgen: l0.kind === 'pool' ? r.poolGen : l0.lender.ownGen,
402	            mgen: m.ownGen,
403	          };
404	          if (l0.kind === 'pool') {
405	            if (r.poolResv.delete(l0)) r.poolResvUnits -= l0.units;
406	            r.poolLinks.add(link);
407	          } else {
408	            const g = l0.lender;
409	            g.usedOwn += l0.units;
410	            g.pendingLends -= l0.units;
411	            lenderCleanup.add(g);
412	            g.inFlight += l0.units;
413	            g.lentInFlight += l0.units;
414	            link.pgen = r.poolGen; // pool window this lend charged
415	            g.lentLinks.add(link);
416	          }
417	          links.push(link);
418	        }
419	        m.borrowedInFlight += units - ownPart;
420	        seg = { member: m, units, own: ownPart, mgen: m.ownGen, links };
421	      }
422	      const rec = { seg };
423	      m.openHandles.add(rec);
424	      records.push(rec);
425	    }
426	    // One entry may borrow from the same ancestor for several sibling
427	    // members; drop its lender registration once, after every link settled.
428	    for (const g of lenderCleanup) g.resvAsLender.delete(entry);
429	    entry.holdsHeld = false;
430	    entry.segs = null;
431	    return makeHandle(records);
432	  }
433	
434	  // --- Queue entry lifecycle ------------------------------------------------
435	
436	  function detachSignal(entry) {
437	    if (entry.signal !== null) {
438	      entry.signal.removeEventListener('abort', entry.onAbort);
439	      entry.signal = null;
440	    }
441	  }
442	
443	  // One queue entry leaves the queue exactly once, and exactly one of
444	  // granted / refused / expired / cancelled moves as a result.
445	  function settleEntry(entry, outcome) {
446	    if (entry.removed) return;
447	    const qRoot = entry.qroot;
448	    entry.removed = true;
449	    qRoot.liveQueued -= 1;
450	    entry.owner.ownedEntries.delete(entry);
451	    clearTimeout(entry.timer);
452	    detachSignal(entry);
453	    for (const charge of entry.waitCharges) charge.gate.waiting -= charge.units;
454	    if (outcome === 'granted') {
455	      // Both singles and combos arrive here holding a gathered reservation;
456	      // the same commit turns provisional promises into the occupation.
457	      const handle = commitCombo(entry);
458	      entry.owner.granted += 1;
459	      entry.resolve(handle);
460	      return;
461	    }
462	    // Expiry, cancellation and refusal give back any hold; none of those
463	    // outcomes itself counts as a reservation rollback.
464	    releaseHolds(entry);
465	    if (outcome === 'refused') {
466	      entry.owner.refused += 1;
467	      entry.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
468	    } else if (outcome === 'cancelled') {
469	      entry.owner.cancelled += 1;
470	      entry.reject(
471	        new QuotaExceededError('CANCELLED', 'queued request was cancelled before quota was available'),
472	      );
473	    } else {
474	      entry.owner.expired += 1;
475	      entry.reject(
476	        new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
477	      );
478	    }
479	  }
480	
481	  // After a queued head leaves outside a window flip (its wait timer fires,
482	  // its signal aborts, a shrink refuses it, or a reparent settles it), the
483	  // requests behind it must be retried at once. The walk follows arrival
484	  // order. A prefix entry whose deadline is already due expires FIRST, even
485	  // when its own timer has not fired yet: at one moment expiry is settled
486	  // before withdrawal and before any grant. Every other prefix entry is
487	  // re-gathered against the CURRENT pool and committed; the walk stops at
488	  // the first that cannot gather — a hold-free entry could not gather
489	  // against this same pool state (the departed head freed nothing), and
490	  // soft overtaking around a blocked combo remains the pool flip's job
491	  // (where the two-yield rule lives). The retry therefore moves no rollback
492	  // counter: a failed attempt simply keeps the entry queued and the next
493	  // window flip gathers it again. Re-gathering (rather than trusting the
494	  // old hold) keeps the commit correct after a flip reclaimed part of the
495	  // hold before an earlier barrier stopped the flip's allocation walk.
496	  // Every settled entry leaves the queue once and the stopping index
497	  // becomes the new head, so the total work across drains is amortized
498	  // linear.
499	  function drainHeld(r) {
500	    const t = rootNow(r);
501	    const q = r.queue;
502	    let i = r.head;
503	    for (; i < q.length; i += 1) {
504	      const entry = q[i];
505	      if (entry.removed) continue;
506	      // Expiry beats the grant at the same moment.
507	      if (entry.deadline <= t) {
508	        settleEntry(entry, 'expired');
509	        continue;
510	      }
511	      if (!entry.holdsHeld) break;
512	      releaseHolds(entry);
513	      let ok;
514	      if (entry.combo) {
515	        ok = tryGather(entry, buildSegs(entry.comboGates, (g) => entry.comboUnits.get(g)));
516	      } else {
517	        ok = tryGatherOne(entry, entry.owner, entry.units);
518	      }
519	      if (!ok) break;
520	      settleEntry(entry, 'granted');
521	    }
522	    // Every slot before i is now removed; pin the head there permanently so
523	    // re-scans across drains never go quadratic.
524	    r.head = i;
525	    while (r.head < q.length && q[r.head].removed) r.head += 1;
526	    if (r.head > 32 && r.head * 2 >= q.length) {
527	      r.queue = q.slice(r.head);
528	      r.head = 0;
529	    }
530	    // minDeadline is left as-is. Settled heads can only make it stale LOW,
531	    // which merely lets the next flip's sweep scan (allocate scans the queue
532	    // anyway); a stale-low shortcut never skips a real expiry, so the drain
533	    // stays prefix-bounded rather than scanning the whole queue.
534	  }
535	
536	  // The wait timer measures real elapsed time, like the baseline. The
537	  // deadline field additionally gates window-flip sweeps when the monotonic
538	  // clock and the wall clock disagree (mocked/frozen clocks). Delays beyond
539	  // the 32-bit timer range fire in chunks so the cap is honoured in full
540	  // instead of overflowing to 1ms.
541	  function armEntry(entry, delay) {
542	    const chunk = Math.min(Math.max(1, delay), MAX_TIMER_DELAY);
543	    entry.timer = setTimeout(() => {
544	      if (entry.removed) return;
545	      const remaining = delay - chunk;
546	      if (remaining > 0) {
547	        armEntry(entry, remaining);
548	        return;
549	      }
550	      const r = entry.qroot;
551	      settleEntry(entry, 'expired');
552	      // A head timing out must not freeze the queue: retry the requests
553	      // behind it in the same event-loop tick.
554	      drainHeld(r);
555	    }, chunk);
556	    if (typeof entry.timer.unref === 'function') entry.timer.unref();
557	  }
558	
559	  // At the same moment expiry beats cancellation: an abort arriving once the
560	  // deadline has already passed settles as WAIT_EXPIRED.
561	  function onEntryAbort(entry) {
562	    if (entry.removed) return;
563	    const r = entry.qroot;
564	    if (entry.deadline <= rootNow(r)) {
565	      settleEntry(entry, 'expired');
566	    } else {
567	      settleEntry(entry, 'cancelled');
568	    }
569	    // A head withdrawal must not stop the queue: retry later arrivals now.
