test('migration feasibility/accounting follow the live draw after lender flips', async (t) => {
  let acc=0, rej=0, problems=0;
  for (let seed=1; seed<=20000; seed++) {
    const rnd=mulberry32(seed); const ri=(n)=>Math.floor(rnd()*n);
    const cfg = {
      LR: 6 + ri(6),           // 6..11
      lp: 1 + ri(3),
      la: 1 + ri(3),
      lleaf: 1 + ri(3),
      U: 1 + ri(9),
      flipP: rnd() < 0.6,
      flipA: rnd() < 0.4,
    };
    // How much leaf actually got: the occupation always commits (member limit
    // never caps; pool LR must cover U). Skip configs that cannot commit.
    const run = (withMove, nFreeOverride) => new Promise((resolve) => {
      t.mock.timers.enable({ apis:['setTimeout','Date'] });
      const tick=(ms)=>t.mock.timers.tick(ms);
      const w = makeWorld(cfg);
      let h=null, commitErr=null;
      w.acquire().then((hh)=>{h=hh;step2();},(e)=>{commitErr=e;step2();});
      function step2(){
        // let lender windows flip
        tick(45);
        if (withMove==='probe') {
          // measure freeR with zero-wait acquires
          w.R.updateMaxWaitMs(0);
          let free=0;
          const tryOne=()=>{
            if (free>cfg.LR) { t.mock.reset(); return resolve(null); }
            w.R.acquire(1).then((hh)=>{ hh.release(); free+=1; tryOne(); },
              ()=>{ t.mock.reset(); resolve(free); });
          };
          tryOne();
          return;
        }
        let code=null;
        if (withMove) {
          const nFree = nFreeOverride;
          const LN = cfg.LR;
          const N = createGate({ limit: LN, windowMs: 1e9 });
          // pre-occupy so N has exactly nFree free
          const need = LN - nFree;
          const pre = (k)=>{
            if (k<=0) return doMove();
            N.acquire(1).then(()=>pre(k-1),(e)=>{ t.mock.reset(); resolve('NpreFail'); });
          };
          const doMove=()=>{
            try { w.leaf.reparent(N); } catch(e){ code=e.code; }
            // post-move invariants
            w.R.updateMaxWaitMs(0); N.updateMaxWaitMs(0);
            const finish=(problem)=>{ t.mock.reset(); resolve({code, problem}); };
            let problem=null;
            if (code==='QUOTA_EXCEEDED') { finish(null); return; }
            // accepted: old pool fully free (subtree was the only R user)
            w.R.acquire(cfg.LR).then(()=>{
              w.R.acquire(1).then(()=>{ problem='old: +1 wrongly granted'; finish(problem); },
                ()=>{
                  // new pool: exactly nFree consumed by moved draw -> 0 free
                  N.acquire(1).then(()=>{ problem='new: still has room'; finish(problem); },
                    ()=>finish(null));
                });
            },(e)=>{ problem='old full not free: '+e.code; finish(problem); });
          };
          pre(need);
        } else { t.mock.reset(); resolve(null); }
      }
    });

    // commit feasibility: only run if U <= LR (pool can cover)
    if (cfg.U > cfg.LR) continue;
    const freeR = await run('probe');
    if (freeR===null) continue;
    const Dlive = cfg.LR - freeR;

    // Move into a new pool with EXACTLY Dlive free: must SUCCEED and balances exact.
    const ok = await run(true, Dlive);
    if (ok && ok.code==='QUOTA_EXCEEDED') { problems++; console.log('seed',seed,'feasible rejected',JSON.stringify(cfg),'Dlive',Dlive); if(problems>6)break; }
    else if (ok && ok.problem) { problems++; console.log('seed',seed,ok.problem,JSON.stringify(cfg),'Dlive',Dlive); if(problems>6)break; }
    else acc++;

    // Move into Dlive-1 free: must REJECT.
    if (Dlive>=1) {
      const rj = await run(true, Dlive-1);
      if (rj && rj.code!=='QUOTA_EXCEEDED') { problems++; console.log('seed',seed,'infeasible accepted',JSON.stringify(cfg),'Dlive',Dlive); if(problems>6)break; }
      else rej++;
    }
  }
  t.mock.reset();
  console.log('accepted-ok',acc,'rejected-ok',rej,'problems',problems);
  assert.equal(problems,0);
});
